parameters.jsCode:
const arr = (v) => [].concat(v || []);
const val = (v) => String(arr(v)[0] ?? '').trim();
const snake = (s) => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '_');

// Centro de comando (trigger): claves como "Nombre" o "Nombre|tipo"
const getT = (o, name) => {
  const k = Object.keys(o).find(k => k === name || k.startsWith(name + '|'));
  return k ? o[k] : undefined;
};
// Directrices (salida simplificada): claves property_<nombre>
const getP = (o, name) => o['property_' + snake(name)];

const trigger = $('Notion Trigger').first().json;
const idea = val(getT(trigger, 'Idea semilla'));
const etiquetas = String(getT(trigger, 'Etiquetas') || '').split(',').map(t => t.trim()).filter(Boolean);
const red_social = val(getT(trigger, 'Red Social'));
const imagen_url = val(getT(trigger, 'URL de imagen'));

const filas = $input.all().map(i => i.json).filter(p => arr(getP(p, 'Red Social')).map(String).includes(red_social));
if (!filas.length) throw new Error(`No hay directrices cargadas para la red social "${red_social}"`);

const fila = (concepto) => filas.find(p => val(getP(p, 'Concepto')).toLowerCase() === concepto.toLowerCase());
const filaLargo = fila('Largo');
const largo_min = Number(getP(filaLargo || {}, 'Largo min'));
const largo_max = Number(getP(filaLargo || {}, 'Largo max'));
const tope_total = Number(getP(filaLargo || {}, 'Tope total'));
if (![largo_min, largo_max, tope_total].every(Number.isFinite) || largo_max <= 0 || tope_total <= 0) {
  throw new Error(`Faltan los límites de largo (Largo min / Largo max / Tope total) para "${red_social}"`);
}

const requiere_imagen = /obligatoria/i.test(val(getP(fila('Imagen') || {}, 'Regla')));
const aviso_etiqueta = /corto/i.test(val(getP(fila('Aviso legal') || {}, 'Regla'))) ? 'Legal corto' : 'Legal';
const directrices = filas.map(p => `- ${val(getP(p, 'Concepto'))}: ${val(getP(p, 'Regla'))}`).join('\n');

return [{ json: { pageId: trigger.id, idea, etiquetas: etiquetas.join(', '), red_social, imagen_url, requiere_imagen, largo_min, largo_max, tope_total, aviso_etiqueta, directrices } }];

const get = (o, name) => {
  const k = Object.keys(o).find(k => k.toLowerCase().startsWith('property_' + name) || k.toLowerCase().startsWith(name));
  return k ? o[k] : undefined;
};
const p = $('Preparar entrada').first().json;

const avisos = $input.all().map(i => String(get(i.json, 'detalle') || '').trim()).filter(Boolean);
if (!avisos.length) {
  throw new Error(`No se encontró el aviso legal (etiqueta ${p.aviso_etiqueta}) en la base de conocimiento`);
}
const aviso = avisos.join('\n');

// El largo de las Directrices es el del texto de la IA, sin el aviso.
// El máximo efectivo también respeta el tope total de la red (texto + salto + aviso).
const separador = 2;
const espacio_min = p.largo_min;
const espacio_max = Math.min(p.largo_max, p.tope_total - aviso.length - separador);
if (espacio_max < Math.max(espacio_min, 60)) {
  throw new Error(`Con el aviso legal (${aviso.length} caracteres) el texto en ${p.red_social} puede tener como máximo ${espacio_max} (mínimo ${espacio_min}, tope total ${p.tope_total}). Usá el aviso corto en las Directrices de esta red.`);
}

return [{ json: { ...p, aviso, espacio_min, espacio_max } }];

const p = $('Calcular espacio y aviso').first().json;
const out = $('AI Agent').first().json.output;
if (!out || !out.cuerpo) throw new Error('El agente no devolvió el campo cuerpo');
const cuerpo = out.cuerpo.trim();
const largo_texto = cuerpo.length;
const cuerpo_final = cuerpo + '\n\n' + p.aviso;
const largo_total = cuerpo_final.length;
const formato_ok = largo_texto >= p.espacio_min && largo_texto <= p.espacio_max && largo_total <= p.tope_total;

return [{
  json: {
    pageId: p.pageId,
    titulo: out.titulo,
    cuerpo_final,
    largo_texto,
    largo_total,
    espacio_min: p.espacio_min,
    espacio_max: p.espacio_max,
    tope_total: p.tope_total,
    formato_ok,
    imagen_url: p.imagen_url,
    etiquetas_consultadas: out.etiquetas_consultadas || [],
    registros_usados: out.registros_usados || [],
    afirmaciones_fuera_de_base: out.afirmaciones_fuera_de_base || [],
    datos_a_verificar: out.datos_a_verificar || []
  }
}];

